#include <vector>
#include <string>
#include <cstddef>
#include <algorithm>
#include <omp.h>

struct Book {
    std::string title;
    int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    const size_t n = books.size();
    if (n == 0) return static_cast<size_t>(-1);

    size_t globalBest = static_cast<size_t>(-1);

    #pragma omp parallel
    {
        size_t localBest = static_cast<size_t>(-1);

        #pragma omp for nowait
        for (size_t i = 0; i < n; ++i) {
            if (books[i].pages < 100) {
                if (localBest == static_cast<size_t>(-1) || i > localBest) {
                    localBest = i;
                }
            }
        }

        #pragma omp critical
        {
            if (localBest != static_cast<size_t>(-1)) {
                if (globalBest == static_cast<size_t>(-1) || localBest > globalBest) {
                    globalBest = localBest;
                }
            }
        }
    }

    return globalBest;
}
